"use client";

import { AnimatePresence, motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type KeyboardEvent, type ReactNode, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a tag input. Pass `value` to control the tags, or `defaultValue` to let it hold its own list. */
export type TagInputProps = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "defaultValue" | "children"> & {
  label: ReactNode;
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (tags: string[]) => void;
  placeholder?: string;
  disabled?: boolean;
};

// Damping 45 is 2 × √500, rounded up: tags close a gap without overshoot.
const GLIDE_SPRING: Transition = { type: "spring", stiffness: 500, damping: 45, mass: 1 };
// A leaving tag only fades, and faster than a tag arrives.
const LEAVE: Transition = { duration: 0.15 };
const SHOWN = { opacity: 1, scale: 1 };

/**
 * Type a word and press Enter or comma to add it as a tag. A new tag scales
 * in, a removed tag fades, and the others glide to close the gap. Backspace
 * in the empty input selects the last tag, then removes it.
 */
export function TagInput({
  label,
  value,
  defaultValue = [],
  onValueChange,
  placeholder,
  disabled = false,
  className,
  ...divProps
}: TagInputProps) {
  const [ownTags, setOwnTags] = useState(defaultValue);
  const [draft, setDraft] = useState("");
  // True after the first Backspace: the last tag is selected and the next Backspace removes it.
  const [armed, setArmed] = useState(false);
  const [announcement, setAnnouncement] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const inputId = useId();
  const reduceMotion = useReducedMotion();
  const tags = value ?? ownTags;
  const lastTag = tags.at(-1);

  const commit = (next: string[], message: string) => {
    if (value === undefined) setOwnTags(next);
    onValueChange?.(next);
    setAnnouncement(message);
  };

  const add = (text: string) => {
    const names = text.split(",").map((name) => name.trim()).filter(Boolean);
    const next = [...tags];
    for (const name of names) {
      // The same word in another case is the same tag.
      if (!next.some((tag) => tag.toLowerCase() === name.toLowerCase())) next.push(name);
    }
    setDraft("");
    const added = next.slice(tags.length);
    if (added.length > 0) commit(next, `${added.join(", ")} added`);
    else if (names.length > 0) setAnnouncement(`${names[0]} is already added`);
  };

  const remove = (tag: string) => {
    setArmed(false);
    commit(tags.filter((other) => other !== tag), `${tag} removed`);
    // The remove button leaves with its tag, so focus returns to the input.
    inputRef.current?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing) return;
    if (event.key === "Enter" && draft.trim()) {
      // Enter adds the tag; with an empty input it is left to submit the form.
      event.preventDefault();
      add(draft);
    } else if (event.key === "Backspace" && draft === "" && lastTag !== undefined) {
      event.preventDefault();
      if (armed) return remove(lastTag);
      setArmed(true);
      setAnnouncement(`${lastTag} selected. Press Backspace again to remove it.`);
    } else {
      setArmed(false);
    }
  };

  return (
    <div {...divProps} className={cn("flex w-full flex-col gap-2", className)}>
      <label htmlFor={inputId} className="text-sm font-medium text-foreground">
        {label}
      </label>
      <div
        className={cn(
          "relative flex min-h-12 flex-wrap items-center gap-2 rounded-xl border border-border bg-background p-2",
          "has-[input:focus-visible]:ring-2 has-[input:focus-visible]:ring-ring has-[input:focus-visible]:ring-offset-2 has-[input:focus-visible]:ring-offset-background",
          disabled && "cursor-not-allowed opacity-50",
        )}
      >
        <ul role="list" className="contents">
          <AnimatePresence mode="popLayout" initial={false}>
            {tags.map((tag) => (
              <motion.li
                key={tag}
                layout={reduceMotion ? false : "position"}
                initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.8 }}
                animate={SHOWN}
                exit={{ opacity: 0, transition: LEAVE }}
                transition={GLIDE_SPRING}
                data-selected={(armed && tag === lastTag) || undefined}
                className={cn(
                  "flex h-8 cursor-default items-center gap-1 rounded-full bg-muted pr-1 pl-3 text-sm font-medium text-foreground",
                  // The selected tag gains an outline, so the cue is a shape and not a colour.
                  armed && tag === lastTag && "ring-2 ring-ring",
                )}
              >
                <span className="max-w-40 truncate">{tag}</span>
                <button
                  type="button"
                  aria-label={`Remove ${tag}`}
                  disabled={disabled}
                  onClick={() => remove(tag)}
                  // The button is 24px; the pseudo-element grows the hit area to 44px.
                  className="relative grid size-6 cursor-pointer touch-manipulation place-items-center rounded-full text-muted-foreground outline-none before:absolute before:-inset-2.5 hover:bg-background hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring motion-safe:transition-colors motion-safe:duration-150 disabled:cursor-not-allowed"
                >
                  <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-3">
                    <path d="m4.53 3.47 3.47 3.47 3.47-3.47 1.06 1.06L9.06 8l3.47 3.47-1.06 1.06L8 9.06l-3.47 3.47-1.06-1.06L6.94 8 3.47 4.53l1.06-1.06Z" />
                  </svg>
                </button>
              </motion.li>
            ))}
          </AnimatePresence>
        </ul>
        <motion.input
          ref={inputRef}
          id={inputId}
          layout={reduceMotion ? false : "position"}
          transition={GLIDE_SPRING}
          value={draft}
          placeholder={placeholder}
          disabled={disabled}
          autoComplete="off"
          enterKeyHint="done"
          onChange={(event) => {
            setArmed(false);
            // Read from the text, not the key, so a comma from a phone keyboard or a paste also adds.
            if (event.target.value.includes(",")) add(event.target.value);
            else setDraft(event.target.value);
          }}
          onKeyDown={handleKeyDown}
          onBlur={() => {
            setArmed(false);
            if (draft.trim()) add(draft);
          }}
          className="-my-1.5 h-11 min-w-24 flex-1 bg-transparent px-1 text-base text-foreground outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed sm:text-sm"
        />
      </div>
      <span role="status" className="sr-only">
        {announcement}
      </span>
    </div>
  );
}
